 \[m_+<p_-,\quad \ell>\frac{1}{(p_--1)^2}.
\]

\label{thm:high}
Let Assumption~\ref{ass1} and \ref{ass2} hold. There exist positive constants $\varepsilon,c,A,B$,  chosen as in Section~\ref{sec:high}
depending only on the structural parameters and the
fixed choice of $\alpha$ in \eqref{eq9}, such that
the following statement holds.

If $(u_0,u_1)\in V\times H$ satisfies
\begin{equation}\label{eq10}
Y_0:=1+\varepsilon(u_0,u_1)>
\left[
\frac{2AB}{c}
\bigl(1+[\mathcal E(0)]_+\bigr)
\right]^{1/r},
\end{equation}
then every corresponding maximal energy solution
satisfies
\begin{equation}\label{eq11}
T_{\max}
\le\frac{2A}{\varepsilon c(r-1)}
Y_0^{1-r}
\end{equation}
and the norm blow-up conclusion \eqref{eq8}.

\label{thm:global}
Let Assumption \ref{ass1} hold and
\begin{equation}\label{eq13}
 \|\nabla u_0\|_2<R,\quad E(0)<d_0,
\end{equation}
then every maximal energy solution supplied by Theorem~\ref{thm:local} is global. Moreover,
\begin{equation}\label{eq14}
c_E\widehat{E}(t) \le E(t)\le C_E\widehat{E}(t).
\end{equation}
 Here 
\[\widehat{E}(t)=\|u_t(t)\|_2^2+\|\nabla u(t)\|_2^2
 +\int_0^t g(t-s)\|\nabla u(t)-\nabla u(s)\|_2^2\,ds.\]

\label{thm:decay}
Under the hypotheses of Theorem~\ref{thm:convex}, suppose
that the function $\mathcal H$ in Assumption~\ref{assadd}
is given by $\mathcal H(s)=s^q$ for some $1\le q<2$.
Then there exist constants $c,C>0$ such that, for all
$t\ge0$,
\begin{equation}\label{eq19}
E(t)\le
\begin{cases}
\displaystyle
CE(0)\exp\left(-c\int_0^t\xi(s)\,ds\right),
& q=1,\\[6pt]
\displaystyle
CE(0)\left(1+c(q-1)\int_0^t\xi(s)\,ds\right)^{-1/(q-1)},
& 1<q<2.
\end{cases}
\end{equation}

\label{thm:super}
Under the hypotheses of Theorem~\ref{thm:global}, suppose that 
$m_+>2$, $u_0\in L^{m(x)}(\Omega)$ and Assumption  \ref{assadd} hold. 
Set
\begin{equation}\label{eq20}
\gamma=\max\left\{\frac{m_+-2}{2},\frac1{m_--1}\right\}.
\end{equation}
Then there is a constant $\widehat{C}>0$ such that
\begin{equation}\label{eq21}
E(t)\le E(0)\left(
\frac{1+\widehat{C}}{1+\log(1+t)}\right)^{1/(\gamma+1)},
\quad t\ge0.
\end{equation}

\label{correctionlemma}
For every $q\ge p_->2$ and $r\in\mathbb R$,
\begin{equation}\label{eq42}
|r|^q\left(
\frac{q-p_-}{q}\log|r|+\frac{p_-}{q^2}
\right)\ge -c_{p_-}(q),
\end{equation}
where the expression at $r=0$ is defined by continuity.
For each fixed $q$, $c_{p_-}(q)$ is the smallest
nonnegative constant for which
\eqref{eq42} holds for all $r\in\mathbb R$.
Consequently, every energy solution satisfies
\begin{equation}\label{eq43}
\begin{aligned}
\int_\Omega |u|^{p(x)}\log|u|\,dx
\ge{}&
\frac{p_-}{2}\left\|u_t\right\|_2^2
+\frac{p_-}{2}
\left(1-\int_0^t g(s)\,ds\right)
\left\|\nabla u\right\|_2^2\\
&+\frac{p_-}{2}\int_0^t g(t-s)\|\nabla u(t)-\nabla u(s)\|_2^2\,ds
-p_-\mathcal E(t).
\end{aligned}
\end{equation}

\label{lem:pairing-estimate}
Assume that Assumptions~\ref{ass1} and~\ref{ass2} hold. For almost every
$t$,
\begin{equation}\label{eq47}
\begin{split}
\frac d{dt}(u,u_t)

\ge{}&
\left(1+\frac {\hat{q}}{2}\right)\|u_t\|_2^2
+\left(\frac{\hat{q}-2}{2}\ell-\frac{1-\ell}{4\mu}\right)\|\nabla u\|_2^2\\
&+\left(1-\frac {\hat{q}}{p_-}\right)
\int_\Omega|u|^{p(x)}\log|u|dx
-\hat{q}\mathcal E(t)-\left|\int_\Omega b(x,u_t)udx\right|,
\end{split}
\end{equation}
where $\hat{q},\mu$ is shown as \eqref{eq46}.

For any $x,y\ge0$, $k\ge2$ and $a>0$, Young's inequality shows
\[
xy^{k-1}\le ay^k+
\frac{(k-1)^{k-1}}{k^k}a^{-(k-1)}x^k
\le ay^k+a^{-(k-1)}x^k.
\]
Take $k=m(x)$, $a=\lambda H^{-\alpha}$, and $\lambda\ge1$. Since
$\lambda^{-(m(x)-1)}\le\lambda^{-1}$, we have 
\begin{equation}\label{eq48}
\begin{aligned}
\left|\int_\Omega b(x,u_t)udx\right|
\le\lambda H^{-\alpha}\int_\Omega|u_t|^{m(x)}dx+\lambda^{-1}\int_\Omega H^{\alpha(m(x)-1)}|u|^{m(x)}dx.
\end{aligned}
\end{equation}
To estimate the second term in the right-hand side of \eqref{eq48}, split $\Omega$ into
$\{|u|\le e\}$ and $\{|u|>e\}$.
For  $\{|u|>e\}$, we have $\log|u|>1$ and
$|u|^{p_-}\le |u|^{p(x)}$. Therefore, 
\begin{equation}
\label{eq49}
\begin{split}
\int_{\{|u|>e\}}|u|^{p_-}\,dx
&\le \int_{\{|u|>e\}}|u|^{p(x)}\log|u|\,dx\\
&=\int_\Omega |u|^{p(x)}\log|u|\,dx
-\int_{\{1\le |u|\le e\}}|u|^{p(x)}\log|u|\,dx\\
&\quad+\int_{\{|u|<1\}}|u|^{p(x)}|\log|u||\,dx\\
&\le \frac{|\Omega|}{ep_-}+\int_\Omega |u|^{p(x)}\log|u|\,dx.
\end{split}
\end{equation}
Here  we used 
\[
\int_{\{|u|<1\}}|u|^{p(x)}|\log|u||\,dx
\le\int_{\{|u|<1\}}\frac1{ep(x)}\,dx
\le\frac{|\Omega|}{ep_-}\]
by \eqref{eq22}.  


Since $|u|^{m(x)}\le e^{m_+}$ on $\{|u|\le e\}$,
H\"{o}lder's inequality and \eqref{eq49} lead to 
\begin{equation}
\label{eq50}
\begin{split}
\int_\Omega |u|^{m(x)}\,dx
&\le e^{m_+}|\Omega|
+\int_{\{|u|>e\}}|u|^{m_+}\,dx\\
&\le e^{m_+}|\Omega|
+|\Omega|^{1-\beta}
\left(\int_{\{|u|>e\}}|u|^{p_-}\,dx\right)^\beta\\
&\le e^{m_+}|\Omega|
+|\Omega|^{1-\beta}
\left(\frac{|\Omega|}{ep_-}+\int_\Omega |u|^{p(x)}\log|u|\,dx\right)^\beta\\
&\le C_1
\left(1+\frac{|\Omega|}{ep_-}+\int_\Omega |u|^{p(x)}\log|u|\,dx\right)^\beta,
\end{split}
\end{equation}
where $C_1=e^{m_+}|\Omega|+|\Omega|^{1-\beta}$, $\beta=m_+/p_-<1$.
Similarly,
\begin{equation}\label{eq51}
\|u\|_2\le C_2
\left(1+\frac{|\Omega|}{ep_-}+\int_\Omega|u|^{p(x)}\log|u|\,dx\right)^{1/p_-},
\quad C_2=\left(e^2|\Omega|+|\Omega|^{1-2/p_-}\right)^{1/2}.
\end{equation}
Since $r/p_-+r/2<1$ by recalling \eqref{eq9},
Cauchy--Schwarz, \eqref{eq51}, and generalized Young's inequality with weights $r/p_-$, $r/2$, and $1-r/p_--r/2$ illustrate 
\begin{align*}
|(u,u_t)|^r
&\le\|u\|_2^r\|u_t\|_2^r\\
&\le C_2^r\left(1+\frac{|\Omega|}{ep_-}+\int_\Omega|u|^{p(x)}\log|u|\,dx\right)^{r/p_-}
\|u_t\|_2^r\\
&\le C_2^r\left(1+\frac{|\Omega|}{ep_-}+\int_\Omega|u|^{p(x)}\log|u|\,dx
+\|u_t\|_2^2\right).
\end{align*}
Here  we used 
\begin{equation}
\label{eq52}
\int_\Omega|u|^{p(x)}\log|u|\,dx
=\int_{\{|u|\ge1\}}|u|^{p(x)}\log|u|\,dx-\int_{\{|u|<1\}}|u|^{p(x)}|\log|u||\,dx
\ge-\frac{|\Omega|}{ep_-}.
\end{equation}

Since
$r(1-\alpha)=1$ by recalling \eqref{eq9}, the preceding estimate entails
\[
\begin{aligned}
Y^r(t)
&\le2^{r-1}\left(H(t)+\varepsilon^r|(u,u_t)|^r\right)\\
&\le2^{r-1}\left[
H(t)+\varepsilon^rC_2^r
\left(1+\frac{|\Omega|}{ep_-}+\int_\Omega|u|^{p(x)}\log|u|\,dx
+\|u_t\|_2^2\right)\right].
\end{aligned}
\]
Using $1\le H(t)/h_*$ and \eqref{eq52}, we obtain \eqref{eq53}
\begin{equation}\label{1517}
A=2^{r-1}\left(
1+\varepsilon^rC_2^r
\max\left\{1,\frac{1+\frac{|\Omega|}{ep_-}}{h_*}\right\}
\right).
\end{equation}
If the source integral is nonnegative, absorbing $1+\frac{|\Omega|}{ep_-}$
into $H(t)$ due to $1+\frac{|\Omega|}{ep_-}\le(1+\frac{|\Omega|}{ep_-})H(t)/h_*$ instead gives \eqref{eq54}, with the same constant $A$. 

In fact, \eqref{eq54} applies when $\mathcal E(t)<0$, otherwise,
we retain form \eqref{eq53}.

\label{lem:firstmult}
Under the hypotheses of Theorem \ref{thm:global} and $m_+\le2^*$,
for almost every $t>0$,
\begin{equation}\label{eq69}
\frac d{dt}(u,u_t)
\le\|u_t\|_2^2-\frac\ell4\|\nabla u\|_2^2
+C\|\nabla w\|_2^2
+C\int_\Omega|u_t|^{m(x)}\,dx,
\end{equation}
where 
\[
w(t):=\int_0^t g(t-s)[u(t)-u(s)]\,ds.
\]

\label{lem:basicL}
Under the hypotheses of Lemmas~\ref{lem:firstmult}
and~\ref{lem:secondmult}, fix $t_0>0$.
There exist constants $N_1,N_2,C_L,c,C>0$ such that
\[
L(t)=N_1E(t)+(u(t),u_t(t))-N_2(u_t(t),w(t))
\]
satisfies
\begin{equation}\label{eq75}
\begin{aligned}
E(t)\le L(t)\le C_LE(t),\quad t\ge t_0
\end{aligned}
\end{equation}
and
\begin{equation}\label{eq76}
L'(t)\le-cE(t)
+C\int_0^t g(t-s)
\|\nabla u(t)-\nabla u(s)\|_2^2\,ds, \quad \text{a.e. } t\ge t_0.
\end{equation}
